mapper.select:
select p.project_id projectId,p.project_no projectNo,p.project_name projectName, p.status status,p.main_owner_user_id mainOwnerUserId,p.main_owner_name mainOwnerName, (select count(*) from biz_project_kpi target where target.project_id=p.project_id and target.status='CURRENT') targetCount, plan.plan_id planId,plan.plan_version planVersion,plan.cycle_end cycleEnd, settlement.settlement_id settlementId,settlement.status settlementStatus, settlement.total_score totalScore,settlement.bonus_amount bonusAmount from biz_project p left join biz_project_kpi_plan plan on plan.plan_id=( select latest.plan_id from biz_project_kpi_plan latest where latest.project_id=p.project_id order by latest.cycle_end desc,latest.plan_version desc limit 1) left join biz_project_kpi_settlement settlement on settlement.plan_id=plan.plan_id where p.del_flag='0'
and coalesce(p.sponsor_owner_user_id,p.initiator_user_id)=#{userId}
and (p.main_owner_user_id=#{userId} or exists( select 1 from biz_project_member member_scope where member_scope.project_id=p.project_id and member_scope.user_id=#{userId} and member_scope.status='0'))
and p.project_id in #{projectId}
order by field(p.status,'ACTIVE','PAUSED','ACCEPTANCE','PLANNING','DRAFT','CLOSED','CANCELED'), p.update_time desc,p.project_id desc

select count(*) from biz_project_kpi_plan
where project_id=#{projectId} and status in('PUBLISHED','CLOSED')
  and cycle_start<=#{cycleEnd} and cycle_end>=#{cycleStart}

mapper.update:
update biz_project_kpi_settlement set total_score=#{totalScore},bonus_amount=#{bonusAmount},
  update_by=#{userName},update_time=sysdate(),version=version+1
where settlement_id=#{settlementId} and status in('DRAFT','RETURNED') and version=#{version}
